 Button Button(string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=32,MinimumSize=new Size(100,30),FlatStyle=FlatStyle.Flat,BackColor=Color.White,Margin=new Padding(3,3,6,3)};b.FlatAppearance.BorderColor=Color.FromArgb(180,196,212);b.Click+=(s,e)=>Run(action);return b;}
 void AddMenu(ToolStripMenuItem menu,string text,Action a,bool configuration){var item=new ToolStripMenuItem(text);item.Click+=(s,e)=>Run(a);menu.DropDownItems.Add(item);if(configuration)configMenu.Add(item);}
 void Run(Action a){try{a();}catch(Exception e){MessageBox.Show(this,e.Message,"Modbus Emulator X",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 void Changed(){dirty=true;Text="Modbus Emulator X — "+project.Name+" *";}
 void Commit(){Validate();if(ActiveControl!=null)ActiveControl.Focus();}
 bool ConfirmDiscard(){if(!dirty)return true;var answer=MessageBox.Show(this,"Save changes to this project?","Modbus Emulator X",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);if(answer==DialogResult.Cancel)return false;if(answer==DialogResult.Yes){try{return Save(false);}catch(Exception e){MessageBox.Show(e.Message);return false;}}return true;}
 bool Replace(Project p,string file){if(!ConfirmDiscard())return false;Stop();if(networkOptions.RemoveOnStop&&ProtectedAliasStore.CountOwned(networkOptions.SessionId)>0)StopServersCommand();timelineRunner=null;project=p;path=file;dirty=false;history.Clear();BindProject();return true;}
 void BindProject(){refreshing=true;projectName.Text=project.Name;devices.DataSource=null;devices.DataSource=project.Devices;RefreshScenarios();RefreshTimelines();refreshing=false;Text="Modbus Emulator X — "+project.Name;BindDevice();}
 void RefreshDeviceNames(){int i=devices.SelectedIndex;devices.DataSource=null;devices.DataSource=project.Devices;if(i>=0&&i<devices.Items.Count)devices.SelectedIndex=i;}
 void BindDevice(){var d=Selected;properties.SelectedObject=d;grid.DataSource=d==null?null:d.Points;heading.Text=d==null?"Add a device to begin":d.ToString()+"  ·  zero-based addresses";history.Clear();}
 void RefreshScenarios(){scenarios.DataSource=null;scenarios.DataSource=project.Scenarios.ToList();}
 string Choose(bool save,string filter,string title,string suggested){using(FileDialog d=save?(FileDialog)new SaveFileDialog():new OpenFileDialog()){d.Filter=filter;d.Title=title;d.FileName=suggested;if(d.ShowDialog(this)==DialogResult.OK)return d.FileName;return null;}}
 bool Save(bool asNew){Commit();if(asNew||string.IsNullOrEmpty(path)){string selected=Choose(true,"Modbus Emulator X project (*.mbx)|*.mbx|Excel project (*.xlsx)|*.xlsx","Save project",SafeName()+".mbx");if(selected==null)return false;ProjectFiles.Save(project,selected);path=selected;}else ProjectFiles.Save(project,path);dirty=false;Text="Modbus Emulator X — "+project.Name;return true;}
 string SafeName(){return string.Concat(project.Name.Select(c=>Path.GetInvalidFileNameChars().Contains(c)?'_':c));}
 void Open(){string f=Choose(false,"Project files (*.mbx;*.xlsx)|*.mbx;*.xlsx","Open project","");if(f!=null){Project p=ProjectFiles.Load(f);Replace(p,f);}}
 void Import(){string f=Choose(false,"Excel project (*.xlsx)|*.xlsx|Excel CSV (*.csv)|*.csv","Import Excel project","");if(f!=null){Project p=ProjectFiles.Load(f);if(Replace(p,null))Changed();}}
 void Export(){Commit();string f=Choose(true,"Excel project (*.xlsx)|*.xlsx|Excel CSV UTF-8 (*.csv)|*.csv","Export Excel project",SafeName()+".xlsx");if(f!=null){if(Path.GetExtension(f).Equals(".csv",StringComparison.OrdinalIgnoreCase)&&(project.Timelines.Count>0||project.Scenarios.Count>0)&&MessageBox.Show(this,"CSV contains only devices and points. Use Excel .XLSX or .MBX to retain timelines and scenarios. Export CSV anyway?","Export CSV",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;ProjectFiles.Save(project,f);pending.Enqueue("EXPORTED "+f);}}
 void AddDevice(){var d=new Device{Name=UniqueDevice(),UnitId=1,Port=1502};while(project.Devices.Any(x=>x.BindAddress==d.BindAddress&&x.Port==d.Port&&x.UnitId==d.UnitId))d.Port++;project.Devices.Add(d);devices.SelectedItem=d;Changed();}
 string UniqueDevice(){int i=1;while(project.Devices.Any(d=>d.Name=="Device "+i))i++;return "Device "+i;}
 void RemoveDevice(){if(Selected==null)return;Device d=Selected;if(MessageBox.Show("Remove "+d.Name+" and all its points?","Remove device",MessageBoxButtons.YesNo)==DialogResult.Yes){foreach(var sc in project.Scenarios){sc.Devices.RemoveAll(x=>x.Name==d.Name);sc.Values.RemoveAll(x=>x.Device==d.Name);}foreach(var t in project.Timelines)t.Steps.RemoveAll(x=>x.Device==d.Name);project.Devices.Remove(d);BindTimeline();Changed();}}
 void AddPoint(){if(Selected==null)return;int address=0;while(Selected.Points.Any(p=>p.Area==Area.HoldingRegister&&address>=p.Address&&address<p.Address+p.Width))address++;var pt=new Point{Name="Register "+address,Address=address};if(EditObject(pt,"New point")){Selected.Points.Add(pt);try{project.Validate();}catch{Selected.Points.Remove(pt);throw;}Changed();}}
 void RemovePoint(){if(SelectedPoint!=null){Point pt=SelectedPoint;foreach(var sc in project.Scenarios)sc.Values.RemoveAll(x=>x.Device==Selected.Name&&x.Point==pt.Name);foreach(var t in project.Timelines)t.Steps.RemoveAll(x=>x.Device==Selected.Name&&x.IsPoint&&x.Point==pt.Name);Selected.Points.Remove(pt);BindTimeline();Changed();}}
 void EditPoint(){Point pt=SelectedPoint;if(pt==null)return;if(engine.Running||simulate)throw new Exception("Stop servers and pause signals to edit point configuration. Use Set live value while running.");var serializer=new System.Xml.Serialization.XmlSerializer(typeof(Point));Point copy;using(var ms=new MemoryStream()){serializer.Serialize(ms,pt);ms.Position=0;copy=(Point)serializer.Deserialize(ms);}if(EditObject(copy,"Point details")){var references=project.Scenarios.SelectMany(sc=>sc.Values).Where(v=>v.Device==Selected.Name&&v.Point==pt.Name).ToList();var timelineRefs=project.Timelines.SelectMany(t=>t.Steps).Where(v=>v.IsPoint&&v.Device==Selected.Name&&v.Point==pt.Name).ToList();int index=Selected.Points.IndexOf(pt);Selected.Points[index]=copy;foreach(var r in references)r.Point=copy.Name;foreach(var r in timelineRefs)r.Point=copy.Name;try{project.Validate();}catch{Selected.Points[index]=pt;foreach(var r in references)r.Point=pt.Name;foreach(var r in timelineRefs)r.Point=pt.Name;throw;}BindTimeline();Changed();}}
 bool EditObject(object obj,string title){using(var f=new Form{Text=title,Width=520,Height=650,StartPosition=FormStartPosition.CenterParent}){var pg=new PropertyGrid{Dock=DockStyle.Fill,SelectedObject=obj,ToolbarVisible=false};var ok=new Button{Text="Apply",Dock=DockStyle.Bottom,Height=38,DialogResult=DialogResult.OK};f.Controls.Add(pg);f.Controls.Add(ok);f.AcceptButton=ok;return f.ShowDialog(this)==DialogResult.OK;}}
 void SetValue(){EnsureTimelineIdle();Point p=SelectedPoint;if(p==null)return;string s=Ask("Set "+p.Name+" ("+p.Units+")",p.Value.ToString(CultureInfo.InvariantCulture));if(s==null)return;double v=double.Parse(s,CultureInfo.InvariantCulture);if(double.IsNaN(v)||double.IsInfinity(v))throw new Exception("Use a finite number.");lock(Selected.Sync){double old=p.Value;p.Value=v;try{p.Encode();}catch{p.Value=old;throw;}p.Simulation=Wave.Manual;}grid.RefreshLiveCells();Changed();}
 string Ask(string title,string value){using(var f=new Form{Text=title,Width=460,Height=160,StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var t=new TextBox{Text=value,Left=16,Top=18,Width=410};var ok=new Button{Text="Apply",Left=245,Top=58,Width=85,DialogResult=DialogResult.OK};var cancel=new Button{Text="Cancel",Left=340,Top=58,Width=85,DialogResult=DialogResult.Cancel};f.Controls.AddRange(new Control[]{t,ok,cancel});f.AcceptButton=ok;f.CancelButton=cancel;return f.ShowDialog(this)==DialogResult.OK?t.Text:null;}}
 void Bulk(){if(Selected==null)return;var settings=new RangeSettings();if(!EditObject(settings,"Add point range"))return;if(settings.Count<1||settings.Count>10000)throw new Exception("Count must be 1..10000.");var added=new List<Point>();try{for(int i=0;i<settings.Count;i++){var p=new Point{Name=settings.Prefix+(settings.Start+i),Address=settings.Start+i,Area=settings.Area,Type=settings.Area==Area.Coil||settings.Area==Area.DiscreteInput?ValueType.Bool:ValueType.UInt16,Value=settings.Value,Default=settings.Value};Selected.Points.Add(p);added.Add(p);}project.Validate();}catch{foreach(var p in added)Selected.Points.Remove(p);throw;}Changed();}

 void Stop(){StopTimeline();simulate=false;try{CancelSequence();}finally{engine.Stop();SetConfiguration(true);}}
 void SetConfiguration(bool enabled){enabled=enabled&&!networkBusy&&!TimelineActive;foreach(var c in config)c.Enabled=enabled;foreach(var item in configMenu)item.Enabled=enabled;properties.Enabled=enabled;}
 void Reset(){EnsureTimelineIdle();simulate=false;foreach(Device d in project.Devices)lock(d.Sync){d.Responding=true;d.DelayMs=0;d.DropPercent=0;d.ExceptionCode=0;foreach(Point p in d.Points)p.Value=p.Default;}SetConfiguration(!engine.Running);grid.RefreshLiveCells();properties.Refresh();Changed();}
 void Faults(){EnsureNoSequence();if(Selected==null)return;var d=Selected;var settings=new FaultSettings{Responding=d.Responding,DelayMs=d.DelayMs,DropPercent=d.DropPercent,ExceptionCode=d.ExceptionCode};if(EditObject(settings,"Live fault controls")){if(settings.DelayMs<0||settings.DelayMs>60000||settings.DropPercent<0||settings.DropPercent>100||settings.ExceptionCode<0||settings.ExceptionCode>11)throw new Exception("Delay 0..60000; drop 0..100; exception 0..11 (0 disables).");d.Responding=settings.Responding;d.DelayMs=settings.DelayMs;d.DropPercent=settings.DropPercent;d.ExceptionCode=settings.ExceptionCode;properties.Refresh();Changed();}}
 void CaptureScenario(){string name=Ask("Scenario name","Scenario "+(project.Scenarios.Count+1));if(string.IsNullOrWhiteSpace(name))return;if(project.Scenarios.Any(x=>x.Name.Equals(name,StringComparison.OrdinalIgnoreCase)))throw new Exception("Choose a unique scenario name.");project.Scenarios.Add(Scenario.Capture(project,name));RefreshScenarios();Changed();}
 void ApplyScenario(){EnsureNoSequence();var sc=scenarios.SelectedItem as Scenario;if(sc==null)return;sc.Apply(project);properties.Refresh();grid.RefreshLiveCells();Changed();pending.Enqueue("SCENARIO "+sc.Name);}
 void RunSequence(){if(!engine.Running)throw new Exception("Start servers before running a scenario sequence.");if(sequence!=null&&!sequence.Completed)throw new Exception("A sequence is already running.");string answer=Ask("Seconds per scenario","5");if(answer==null)return;double interval=double.Parse(answer,CultureInfo.InvariantCulture);string output=Choose(true,"Evidence CSV (*.csv)|*.csv","Save scenario stimulus evidence","Scenario evidence.csv");if(output==null)return;simulate=false;sequence=new ScenarioSequence(project,interval,output);sequenceBegan=DateTime.UtcNow;pending.Enqueue("SEQUENCE STARTED");}
 void CancelSequence(){if(sequence!=null&&!sequence.Completed){sequence.Cancel((DateTime.UtcNow-sequenceBegan).TotalSeconds);pending.Enqueue("SEQUENCE CANCELLED; initial state restored");}}
 void Tick(){TickTimeline();if(sequence!=null&&!sequence.Completed){try{sequence.Advance((DateTime.UtcNow-sequenceBegan).TotalSeconds);if(sequence.Completed)pending.Enqueue("SEQUENCE COMPLETED; initial state restored");}catch(Exception ex){pending.Enqueue("SEQUENCE FAILED: "+ex.Message);}}if(simulate){Signals.Update(project,(DateTime.UtcNow-began).TotalSeconds,random);dirty=true;}if(engine.Writes!=lastWrites){lastWrites=engine.Writes;Changed();}
  string line;int n=0;while(n++<500&&pending.TryDequeue(out line)){log.Enqueue(line);trafficDirty=true;while(log.Count>1500)log.Dequeue();}if(trafficDirty&&traffic.Visible&&followTraffic.Checked){traffic.Lines=log.ToArray();traffic.SelectionStart=traffic.TextLength;traffic.ScrollToCaret();trafficDirty=false;}
  grid.RefreshLiveCells();Point selected=SelectedPoint;if(selected!=null&&(engine.Running||simulate||(sequence!=null&&!sequence.Completed)||history.Count==0||!history[history.Count-1].Equals(selected.Value))){history.Add(selected.Value);if(history.Count>240)history.RemoveAt(0);if(plot.Visible)plot.Invalidate();}status.Text=(engine.Running?"RUNNING":"STOPPED")+"  |  "+project.Devices.Count+" devices  |  "+project.Devices.Sum(d=>d.Points.Count)+" points  |  "+engine.Connections+" clients  |  "+engine.Requests+" requests  |  "+engine.Writes+" writes  |  "+engine.Errors+" exceptions  |  Signals: "+(simulate?"running":"paused");
 }
 void DrawPlot(object sender,PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;Point p=SelectedPoint;if(p==null){g.DrawString("Select a point in Points & live values to see its trend.",Font,Brushes.Gray,24,24);return;}using(var titleFont=new Font(Font.FontFamily,15,FontStyle.Bold))g.DrawString(p.Name+"   "+p.Value.ToString("0.###")+" "+p.Units,titleFont,Brushes.DarkSlateGray,24,18);if(history.Count<2)return;double lo=history.Min(),hi=history.Max();if(hi-lo<0.001){lo-=1;hi+=1;}Rectangle r=new Rectangle(75,65,Math.Max(10,plot.Width-105),Math.Max(10,plot.Height-120));for(int i=0;i<6;i++){int y=r.Top+i*r.Height/5;g.DrawLine(Pens.LightGray,r.Left,y,r.Right,y);g.DrawString((hi-(hi-lo)*i/5).ToString("0.##"),Font,Brushes.Gray,8,y-8);}var points=new PointF[history.Count];for(int i=0;i<history.Count;i++)points[i]=new PointF(r.Left+i*r.Width/(float)(history.Count-1),r.Bottom-(float)((history[i]-lo)/(hi-lo)*r.Height));using(var pen=new Pen(Color.FromArgb(0,130,180),2))g.DrawLines(pen,points);g.DrawString(history.Count+" samples · engineering units",Font,Brushes.Gray,r.Left,r.Bottom+18);}
 void ExportLog(){string f=Choose(true,"Text log (*.txt)|*.txt","Export traffic log","traffic.txt");if(f!=null)File.WriteAllLines(f,log.ToArray());}
 async void Probe(){Device d=Selected;if(d==null||d.Points.Count==0){MessageBox.Show("Select a device with at least one point.");return;}if(d.Transport!=Transport.Tcp){MessageBox.Show("The built-in probe is for TCP devices. Use a serial master to test RTU.");return;}Point p=d.Points[0];string host=d.BindAddress=="0.0.0.0"?"127.0.0.1":d.BindAddress;int port=d.Port,unit=d.UnitId,address=p.Address,count=p.Width;byte f=(byte)(p.Area==Area.Coil?1:p.Area==Area.DiscreteInput?2:p.Area==Area.HoldingRegister?3:4);try{string result=await Task.Run(()=>{using(var c=new TcpClient()){var connect=c.BeginConnect(host,port,null,null);using(connect.AsyncWaitHandle){if(!connect.AsyncWaitHandle.WaitOne(3000))throw new Exception("Connection timed out.");}c.EndConnect(connect);c.ReceiveTimeout=3000;c.SendTimeout=3000;byte[] req={0,1,0,0,0,6,(byte)unit,f,0,0,0,0};Engine.Put(req,8,address);Engine.Put(req,10,count);var stream=c.GetStream();stream.Write(req,0,req.Length);byte[] header=ReadProbe(stream,7);byte[] response=ReadProbe(stream,Engine.U(header,4)-1);return "Endpoint "+host+":"+port+" unit "+unit+"\r\nResponse: "+BitConverter.ToString(response);}});if(!IsDisposed)MessageBox.Show(this,result,"TCP probe");}catch(Exception e){if(!IsDisposed)MessageBox.Show(this,e.Message,"TCP probe");}}
 static byte[] ReadProbe(Stream s,int count){if(count<1||count>253)throw new Exception("Invalid response length.");byte[] b=new byte[count];int n=0;while(n<count){int r=s.Read(b,n,count-n);if(r==0)throw new EndOfStreamException();n+=r;}return b;}
 protected override void Dispose(bool disposing){if(disposing){timer.Dispose();engine.Dispose();}base.Dispose(disposing);}
}
public class RangeSettings{public string Prefix{get;set;}public int Start{get;set;}public int Count{get;set;}public Area Area{get;set;}public double Value{get;set;}public RangeSettings(){Prefix="Register ";Count=16;Area=Area.HoldingRegister;}}
public class FaultSettings{public bool Responding{get;set;}public int DelayMs{get;set;}public int DropPercent{get;set;}public int ExceptionCode{get;set;}}
public static class Program{[STAThread]public static void Main(string[] args){if(args.Length>0&&args[0]=="--network-helper"){Environment.ExitCode=NetworkElevation.HelperMain(args);return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{string file=args.Length==2&&args[0]=="--project"?args[1]:args.Length==1?args[0]:null;Application.Run(file==null?new MainForm():new MainForm(ProjectFiles.Load(file),Path.GetExtension(file).Equals(".csv",StringComparison.OrdinalIgnoreCase)?null:file));}catch(Exception e){File.WriteAllText(Path.Combine(Path.GetTempPath(),"ModbusEmulatorX-startup-error.txt"),e.ToString());MessageBox.Show(e.Message,"Modbus Emulator X startup error");}}}
